svg.script:
//
    (function() {
      'use strict';

      // Elements
      var terrIlio = document.getElementById('a12p6-terr-ilio');
      var terrIsquio = document.getElementById('a12p6-terr-isquio');
      var terrPubis = document.getElementById('a12p6-terr-pubis');
      var btnReset = document.getElementById('a12p6-btn-reset');

      var arc1 = document.getElementById('a12p6-arc-1');
      var arc2 = document.getElementById('a12p6-arc-2');
      var arc3 = document.getElementById('a12p6-arc-3');

      var badgeIlio = document.getElementById('a12p6-badge-ilio');
      var badgeIsquio = document.getElementById('a12p6-badge-isquio');
      var badgePubis = document.getElementById('a12p6-badge-pubis');

      var statusBg = document.getElementById('a12p6-status-bg');
      var statusTitle = document.getElementById('a12p6-status-title');
      var msgLine1 = document.getElementById('a12p6-msg-line1');
      var msgLine2 = document.getElementById('a12p6-msg-line2');
      var msgLine3 = document.getElementById('a12p6-msg-line3');
      var msgLine4 = document.getElementById('a12p6-msg-line4');
      var refText = document.getElementById('a12p6-ref-text');

      // State tracking
      var sequence = [];
      var expectedSequence = ['ilio', 'isquio', 'pubis'];

      function resetAll() {
        sequence = [];
        terrIlio.setAttribute('data-active', 'false');
        terrIsquio.setAttribute('data-active', 'false');
        terrPubis.setAttribute('data-active', 'false');

        arc1.setAttribute('data-lit', 'false');
        arc1.removeAttribute('data-error');
        arc2.setAttribute('data-lit', 'false');
        arc2.removeAttribute('data-error');
        arc3.setAttribute('data-lit', 'false');
        arc3.removeAttribute('data-error');

        badgeIlio.setAttribute('data-state', 'neutral');
        badgeIsquio.setAttribute('data-state', 'neutral');
        badgePubis.setAttribute('data-state', 'neutral');

        statusBg.setAttribute('fill', 'var(--a12p6-orientacao, #F3BE5B)');
        statusTitle.setAttribute('fill', '#1A1423');
        statusTitle.textContent = 'AGUARDANDO ATIVAÇÃO (0/3)';

        msgLine1.textContent = 'Validação Anatômica do Quadril:';
        msgLine1.setAttribute('fill', 'var(--a12p6-tinta, #F7F1F5)');
        msgLine2.textContent = 'Selecione os territórios ósseos no osso';
        msgLine3.textContent = 'para percorrer a rotação mnemônica';
        msgLine4.textContent = 'L (Ílio) → S (Ísquio) → P (Púbis).';
        refText.textContent = 'Vista Lateral · Frente da Paciente à Esquerda';
      }

      function handleTerritoryClick(id) {
        // If already completed or in error, reset first if clicking out of step
        var nextExpected = expectedSequence[sequence.length];

        if (id === nextExpected) {
          // Correct step in sequence!
          sequence.push(id);

          if (id === 'ilio') {
            terrIlio.setAttribute('data-active', 'true');
            arc1.setAttribute('data-lit', 'true');
            badgeIlio.setAttribute('data-state', 'active');

            statusBg.setAttribute('fill', 'var(--a12p6-ilio, #5DA9D6)');
            statusTitle.setAttribute('fill', '#FFFFFF');
            statusTitle.textContent = 'PASSO 1/3: í - L - io ATIVADO';

            msgLine1.textContent = '1. ÍLIO · Posição SUPERIOR (12h)';
            msgLine1.setAttribute('fill', 'var(--a12p6-ilio, #5DA9D6)');
            msgLine2.textContent = 'Primeiro território da regra L-S-P.';
            msgLine3.textContent = 'Forma a porção superior do acetábulo.';
            msgLine4.textContent = 'Próximo passo esperado: 2. Ísquio (4h).';
            refText.textContent = '1. Ílio (Superior) → Ativado com Sucesso!';

          } else if (id === 'isquio') {
            terrIsquio.setAttribute('data-active', 'true');
            arc2.setAttribute('data-lit', 'true');
            badgeIsquio.setAttribute('data-state', 'active');

            statusBg.setAttribute('fill', 'var(--a12p6-isquio, #A978C7)');
            statusTitle.setAttribute('fill', '#FFFFFF');
            statusTitle.textContent = 'PASSO 2/3: í - S - quio ATIVADO';

            msgLine1.textContent = '2. ÍSQUIO · Posição POSTERIOR (4h)';
            msgLine1.setAttribute('fill', 'var(--a12p6-isquio, #A978C7)');
            msgLine2.textContent = 'Segundo território no sentido horário.';
            msgLine3.textContent = 'Localizado posterior e inferiormente.';
            msgLine4.textContent = 'Próximo passo esperado: 3. Púbis (8h).';
            refText.textContent = '2. Ísquio (Posterior/Inferior) → Ativado!';

          } else if (id === 'pubis') {
            terrPubis.setAttribute('data-active', 'true');
            arc3.setAttribute('data-lit', 'true');
            badgeIlio.setAttribute('data-state', 'complete');
            badgeIsquio.setAttribute('data-state', 'complete');
            badgePubis.setAttribute('data-state', 'complete');

            statusBg.setAttribute('fill', 'var(--a12p6-sucesso, #4EBE89)');
            statusTitle.setAttribute('fill', '#FFFFFF');
            statusTitle.textContent = 'SEQUÊNCIA COMPLETA ✓ (3/3)';

            msgLine1.textContent = '3. PÚBIS · Posição ANTERIOR (8h)';
            msgLine1.setAttribute('fill', 'var(--a12p6-sucesso, #4EBE89)');
            msgLine2.textContent = 'Mnemônico L-S-P concluído com sucesso!';
            msgLine3.textContent = 'Rotação horária validada no quadril esquerdo:';
            msgLine4.textContent = 'Ílio (sup) → Ísquio (post) → Púbis (ant).';
            refText.textContent = 'Orientação Correta Validada no Sentido Horário!';
          }

        } else {
          // Out of sequence click! Signal orientation error without harsh fail
          statusBg.setAttribute('fill', 'var(--a12p6-erro, #D85C6A)');
          statusTitle.setAttribute('fill', '#FFFFFF');
          statusTitle.textContent = 'ORIENTAÇÃO INVERTIDA ⚠';

          msgLine1.textContent = 'Sentido de Rotação Incorreto:';
          msgLine1.setAttribute('fill', 'var(--a12p6-erro, #D85C6A)');
          msgLine2.textContent = 'A sequência L-S-P exige rotação horária:';
          msgLine3.textContent = '1. Ílio (sup) → 2. Ísquio (post) → 3. Púbis (ant).';
          msgLine4.textContent = 'Siga a ordem correta para fixar a orientação.';
          refText.textContent = 'Alerta: A ordem deve seguir o sentido horário!';

          if (sequence.length === 0) {
            badgeIlio.setAttribute('data-state', 'error');
          } else if (sequence.length === 1) {
            badgeIsquio.setAttribute('data-state', 'error');
          }
        }
      }

      // Event Listeners
      function attachEvents(el, id) {
        el.addEventListener('click', function() {
          handleTerritoryClick(id);
        });
        el.addEventListener('keydown', function(e) {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            handleTerritoryClick(id);
          }
        });
      }

      attachEvents(terrIlio, 'ilio');
      attachEvents(terrIsquio, 'isquio');
      attachEvents(terrPubis, 'pubis');

      btnReset.addEventListener('click', resetAll);
      btnReset.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          resetAll();
        }
      });

      // Initial state
      resetAll();

    })();
  //
